#include <vector>

int main() {
    int n;
    std::cin >> n;
    int o = n + 1;
    std::vector<int> array(n);
    for (int i = 0; i < n; i++) {
        array[i] = i + 1;
    }
    int m;
    std::cin >> m;
    for (int j = 0; j < m; j++) {
        int r;
        std::cin >> r;
        for (int l = r - 1; l < o - 1; l++) {
            array[l] = r;
        }
        if (r < o) {
            o = r;
        }
    }
    for (int i = 0; i < n; i++) {
        std::cout << array[i] << " ";
    }
    return 0;
}

